-    action: () => Promise<Result>, dest?: string,
-  ): Promise<Result> {
-    try {
-      options.signal?.throwIfAborted();
-      const result = await action();
-      options.signal?.throwIfAborted();
-      return result;
-    } catch (error) {
-      throw this.error(error, syscall, path, options, dest);
-    }
-  }
