-  private components(path: string): Component[] {
-    validatePath(path);
-    if (!path) fail("ENOENT");
-    const parts: Component[] = path.split("/").filter(Boolean).map((name) => ({ name }));
-    if (path.endsWith("/")) parts.push({ name: ".", trailing: true });
-    return parts;
-  }
