-    if (path === mount.path && stat?.type !== "directory") fail(stat ? "ENOTDIR" : "ENOENT");
-    const synthetic = this.protected(path) && stat?.type !== "directory";
-    return { path, mount, local, stat: synthetic ? syntheticStat : stat, synthetic };
-  }
