-      }
-      if (component.name === ".") continue;
-      if (component.name === "..") {
-        if (boundary && current.path === boundary.path) fail("EACCES");
-        if (stack.length > 1) stack.pop();
-        if (boundary && stack[stack.length - 1]!.mount !== boundary) fail("EACCES");
